
"use client";
import React,{useEffect,useRef,useState,useId,useMemo} from 'react';
import {createPortal} from 'react-dom';
import {currencies,today,summary,lineSummary,rateFor,quoteShipment,available,voided,effectiveParty,allocationRows,fillAllocations,currentFreight,items,covered,due,decimal,money,fixed,sum,rounded,uuid} from '../lib/accounting.mjs';
import {productTemplate,importProducts,download} from '../lib/spreadsheet.mjs';
const cash=v=>{const [a,b='00']=String(v??'0.00').split('.');try{return BigInt(a).toLocaleString('en-US')+'.'+b.padEnd(2,'0').slice(0,2);}catch{return '—';}};
const price=v=>String(v??'').replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,'');
const idName=(users,id)=>users.find(u=>u.id===id)?.username||'—';
const routeNow=()=>typeof window==='undefined'?['dashboard']:window.location.hash.replace(/^#\/?/,'').split('/').filter(Boolean);
async function api(path,{data,key,form}={}){
  const response=await fetch('/api'+path,{method:data!==undefined||form?'POST':'GET',credentials:'same-origin',
    headers:data!==undefined||form?{...(form?{}:{'Content-Type':'application/json'}),'Idempotency-Key':key||uuid()}:undefined,
    body:form||(data!==undefined?JSON.stringify(data):undefined)});
  const payload=await response.json();
  if(!response.ok){if(response.status===401)window.dispatchEvent(new Event('session-expired'));throw Error(payload.error||'请求失败，请重试。');}
  return payload;
}
async function getDownload(path,filename){
  const response=await fetch('/api'+path,{credentials:'same-origin'});
  if(!response.ok)throw Error((await response.json()).error||'下载失败。');
  download(new Uint8Array(await response.arrayBuffer()),filename,'application/zip');
}
function Field({label,help,children,wide=false}){const id=useId();return <div className={'field '+(wide?'wide':'')}><label htmlFor={id}>{label}</label>{React.cloneElement(children,{id})}{help&&<small>{help}</small>}</div>;}
function Combo({value,onChange,options=[],id,required=false,readOnly=false,placeholder=''}) {
  const [open,setOpen]=useState(false),[all,setAll]=useState(false),[position,setPosition]=useState({}),inputRef=useRef(null);
  const locate=()=>{if(!inputRef.current)return;const r=inputRef.current.getBoundingClientRect(),above=innerHeight-r.bottom<160;setPosition({left:Math.max(8,Math.min(r.left,innerWidth-260)),top:above?Math.max(8,r.top-225):r.bottom+4,width:Math.min(Math.max(250,r.width),innerWidth-16)});};
  useEffect(()=>{const close=e=>{if(e?.target?.closest?.('.combo-options'))return;setOpen(false);};window.addEventListener('resize',close);document.addEventListener('scroll',close,true);return()=>{window.removeEventListener('resize',close);document.removeEventListener('scroll',close,true);};},[]);
  const choices=options.filter(v=>all||!value||v.toLowerCase().includes(value.toLowerCase())).slice(0,80);
  return <div className="combo"><input ref={inputRef} id={id} value={value||''} required={required} readOnly={readOnly} placeholder={placeholder} autoComplete="off" role="combobox" aria-expanded={open} onFocus={()=>{locate();setAll(false);setOpen(!readOnly);}} onBlur={()=>setTimeout(()=>setOpen(false),120)} onChange={e=>{onChange(e.target.value);setAll(false);setOpen(true);}}/>
    <button type="button" tabIndex={-1} aria-label="展开已保存的名称" disabled={readOnly} onMouseDown={e=>e.preventDefault()} onClick={()=>{locate();setAll(true);setOpen(!open);}}>⌄</button>
    {open&&!readOnly&&createPortal(<div className="combo-options" style={position} role="listbox">{choices.map(v=><div role="option" aria-selected={v===value} key={v} onMouseDown={e=>{e.preventDefault();onChange(v);setOpen(false);}}>{v}</div>)}{!choices.length&&<small>暂无匹配名称，可输入新名称</small>}</div>,document.body)}</div>;
}
function Select({value,onChange,id,children,required=true}){return <select id={id} value={value} onChange={e=>onChange(e.target.value)} required={required}>{children}</select>;}
function Currency({value,onChange,id}){return <Select id={id} value={value} onChange={onChange}>{currencies.map(c=><option key={c}>{c}</option>)}</Select>;}
function NumberInput({value,onChange,id,required=true,step='0.01',min='0',readOnly=false,max,placeholder=''}){return <input id={id} type="number" inputMode="decimal" value={value??''} onChange={e=>onChange(e.target.value)} required={required} step={step} min={min} max={max} readOnly={readOnly} placeholder={placeholder}/>;}
function DateInput({value,onChange,id,required=true}){return <input id={id} type="date" value={value} onChange={e=>onChange(e.target.value)} required={required}/>;}
function Button({children,onClick,type='button',secondary=false,disabled=false}){return <button type={type} onClick={onClick} disabled={disabled} className={'btn '+(secondary?'secondary':'primary')}>{children}</button>;}
function Heading({title,sub,children}){return <div className="page-heading"><div><div className="eyebrow">ORDER WORKSPACE</div><h1>{title}</h1>{sub&&<p>{sub}</p>}</div><div className="actions">{children}</div></div>;}
function Empty({children}){return <div className="empty">{children||'暂无记录'}</div>;}
function Money({amount,currency}){return <span className="money">{cash(amount)}{currency&&<small> {currency}</small>}</span>;}
function Panel({title,sub,children,actions}){return <section className="panel">{title&&<div className="panel-heading"><div><h2>{title}</h2>{sub&&<p>{sub}</p>}</div>{actions&&<div className="actions">{actions}</div>}</div>}{children}</section>;}
function ProductName({line}){return <><strong>{line.product}</strong><small>{line.model}</small></>;}

export default function Workspace(){
  const [user,setUser]=useState(null),[ready,setReady]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false);
  const [orders,setOrders]=useState([]),[users,setUsers]=useState([]),[hints,setHints]=useState({}),[route,setRoute]=useState(['dashboard']),[order,setOrder]=useState(null);
  const dirty=useRef(false),initial=useRef(true);
  const view=route[0]||'dashboard',orderId=['order','lines','receipt','payment','allocation','shipment','shipment-edit','correction'].includes(view)?route[1]:null;
  const refresh=async(id=orderId)=>{const [a,b]=await Promise.all([api('/orders'),api('/users')]);setOrders(a.orders);setHints(a.suggestions);setUsers(b.users);if(id){const current=await api('/orders/'+id);setOrder(current.order);}};
  const go=path=>{if(dirty.current&&!window.confirm('当前草稿尚未保存，确定离开？'))return;dirty.current=false;window.location.hash='/'+path;setError('');setNotice('');};
  const run=async(fn)=>{if(busy)return;setBusy(true);setError('');setNotice('');try{return await fn();}catch(e){setError(e.message);return null;}finally{setBusy(false);}};
  const saved=async(result,path)=>{dirty.current=false;await refresh(result.orderId);if(path)go(path);setNotice('已保存，数据与余额已更新。');};
  useEffect(()=>{
    const hash=()=>{setRoute(routeNow().length?routeNow():['dashboard']);setError('');},expired=()=>{setUser(null);setError('登录已过期，请重新登录。');};
    const changed=e=>{if(e.target.closest?.('form[data-draft]'))dirty.current=true;};
    const before=e=>{if(dirty.current){e.preventDefault();e.returnValue='';}};
    const wheel=e=>{const input=document.activeElement;if(input instanceof HTMLInputElement&&['number','date','time'].includes(input.type))e.preventDefault();};
    window.addEventListener('hashchange',hash);window.addEventListener('session-expired',expired);window.addEventListener('beforeunload',before);
    document.addEventListener('input',changed);document.addEventListener('wheel',wheel,{passive:false,capture:true});hash();
    api('/session').then(data=>setUser(data.user)).catch(e=>setError(e.message)).finally(()=>setReady(true));
    return ()=>{window.removeEventListener('hashchange',hash);window.removeEventListener('session-expired',expired);window.removeEventListener('beforeunload',before);document.removeEventListener('input',changed);document.removeEventListener('wheel',wheel,true);};
  },[]);
  useEffect(()=>{if(user)refresh().catch(e=>setError(e.message));},[user?.id]);
  useEffect(()=>{let live=true;if(user&&orderId){setOrder(null);api('/orders/'+orderId).then(data=>{if(live)setOrder(data.order);}).catch(e=>{if(live)setError(e.message);});}return()=>{live=false;};},[orderId,user?.id]);
  const props={user,users,hints,order,go,run,busy,saved,setNotice};
  if(!ready)return <div className="loading">正在连接工作台…</div>;
  if(!user)return <Login onLogin={setUser} run={run} busy={busy} error={error}/>;
  const names={dashboard:'业务总览',orders:'订单工作台',finance:'财务流水',shipments:'发货与物流',help:'使用说明',team:'账号与权限','new-order':'新建订单',order:order?.number||'订单详情',lines:'表格录入产品',receipt:'客户收款',payment:'供应商付款',allocation:'批量分摊',shipment:'新建发货','shipment-edit':'后补运费 / 物流',correction:'更正 / 冲销'};
  return <div className="app-shell"><aside className="sidebar"><a className="brand" href="#/dashboard"><span>▦</span><div>订单中枢<small>AI ORDER TRACKING</small></div></a><div className="workspace-label">在线试用工作台</div><nav>{[['dashboard','◫','业务总览'],['orders','▤','订单工作台'],['finance','⇄','财务流水'],['shipments','▱','发货与物流'],['help','?','使用说明'],...(user.role==='admin'?[['team','♧','账号与权限']]:[])].map(([key,icon,label])=><button key={key} className={view===key?'active':''} onClick={()=>go(key)}><span>{icon}</span>{label}</button>)}</nav><div className="sidebar-bottom"><small>试用数据与本机系统独立</small><div className="profile"><b>{user.username.slice(0,1).toUpperCase()}</b><div>{user.username}<small>{user.role==='admin'?'管理员 · 全部订单':'业务员 · 我的订单'}</small></div></div><button className="logout" onClick={()=>run(async()=>{await api('/logout',{data:{}});dirty.current=false;setUser(null);})}>退出登录 →</button></div></aside>
    <div className="main"><header><span>工作空间 <i>/</i> {names[view]||'工作台'}</span><span className="trial-badge">在线试用</span></header><main>
    {error&&<div className="notice error" role="alert">{error}</div>}{notice&&<div className="notice success" role="status">{notice}</div>}
    {orderId&&!order?<div className="loading">正在读取订单…</div>:
      view==='dashboard'?<Dashboard orders={orders} {...props}/>:
      view==='orders'?<Orders orders={orders} {...props}/>:
      view==='new-order'?<NewOrder {...props}/>:
      view==='order'?<OrderDetail {...props}/>:
      view==='lines'?<LineEntry key={orderId} {...props}/>:
      ['receipt','payment'].includes(view)?<TransactionEntry key={view+orderId} kind={view} {...props}/>:
      view==='allocation'?<AllocationEntry key={route.join('/')} transactionId={route[2]} {...props}/>:
      view==='shipment'?<ShipmentEntry key={orderId} {...props}/>:
      view==='shipment-edit'?<ShipmentEdit key={route.join('/')} shipmentId={route[2]} {...props}/>:
      view==='correction'?<Correction key={route.join('/')} transactionId={route[2]} {...props}/>:
      view==='finance'?<Finance orders={orders} {...props}/>:
      view==='shipments'?<AllShipments orders={orders} {...props}/>:
      view==='team'&&user.role==='admin'?<Team {...props}/>:<Help/>}
    <footer>订单中枢 <span>独立补单 · 精确分摊 · 分批发货</span></footer></main></div></div>;
}
function Login({onLogin,run,busy,error}){
  const [username,setUsername]=useState(''),[password,setPassword]=useState('');
  return <div className="login-shell"><div className="login-story"><div className="brand"><span>▦</span>订单中枢</div><div><div className="eyebrow">A CLEARER WAY TO FOLLOW ORDERS</div><h1>从一笔订单，<br/>到每一批交付。</h1><p>产品、款项和发货在同一处核对。<br/>先收付款，按产品分摊，按实际进度交付。</p></div><small>独立在线试用环境 · 请使用分配给你的账号</small></div><div className="login-panel"><form onSubmit={e=>{e.preventDefault();run(async()=>onLogin((await api('/login',{data:{username,password}})).user));}}><span className="trial-badge">AI 跟单系统</span><h2>登录工作台</h2><p>使用系统账号，无需 ChatGPT 账号。</p>{error&&<div className="notice error" role="alert">{error}</div>}<Field label="账号"><input name="username" value={username} onChange={e=>setUsername(e.target.value)} required autoComplete="username"/></Field><Field label="密码"><input name="password" type="password" value={password} onChange={e=>setPassword(e.target.value)} required autoComplete="current-password"/></Field><Button type="submit" disabled={busy}>{busy?'正在登录…':'进入工作台 →'}</Button><small>试用环境与原系统数据分开保存。</small></form></div></div>;
}
function Dashboard({orders,go,user,users}){
  const totals={};let payableTotal=0n,quantity=0,shipped=0,pending=0;
  orders.forEach(o=>{for(const [c,t]of Object.entries(o.summary.currencies)){totals[c]??={sale:0n,receipt:0n,receivable:0n};for(const key of Object.keys(t))totals[c][key]+=money(t[key]);}payableTotal+=money(o.summary.payable);quantity+=o.summary.quantity;shipped+=o.summary.shipped;pending+=o.summary.unallocated;});
  return <><Heading title="业务总览" sub="先看待办，再进入订单处理产品、款项与发货。"><Button onClick={()=>go('new-order')}>＋ 新建订单</Button></Heading><div className="metrics"><div className="metric"><span>销售 / 待收</span>{Object.entries(totals).map(([c,t])=><div key={c}><strong>{cash(fixed(t.sale))}<small> {c}</small></strong><small>待收 {cash(fixed(t.receivable))}</small></div>)}{!Object.keys(totals).length&&<strong>—</strong>}</div><div className="metric"><span>待付供应商 · CNY</span><strong>{cash(fixed(payableTotal))}</strong><small>自供货仅保留内部成本</small></div><div className="metric"><span>已发 / 总数量</span><strong>{shipped.toLocaleString()} <small>/ {quantity.toLocaleString()}</small></strong><small>按产品数量统计</small></div><div className="metric"><span>待分摊流水</span><strong>{pending}<small> 笔</small></strong><small>录入后分摊，才更新产品余额</small></div></div><Panel title="正在跟进" sub="相同型号的不同补单保持独立。"><OrderList orders={orders.filter(o=>o.status==='active').slice(0,8)} go={go} users={users}/></Panel><div className="workflow-card"><div><h2>一条清楚的录入路径</h2><p>① 建订单和产品 → ② 录入收付款 → ③ 按产品分摊 → ④ 发货 → ⑤ 后补运费与物流</p></div><Button secondary onClick={()=>go('help')}>查看操作说明</Button></div></>;
}
function OrderList({orders,go,users=[]}){return !orders.length?<Empty>还没有订单。点击“新建订单”开始录入。</Empty>:<div className="table-wrap"><table><thead><tr><th scope="col">订单 / 客户</th><th scope="col">业务员</th><th scope="col">销售与待收</th><th scope="col">待付 CNY</th><th scope="col">发货数量</th><th scope="col">状态</th><th scope="col"></th></tr></thead><tbody>{orders.map(o=><tr key={o.id}><td><button className="link order-link" onClick={()=>go('order/'+o.id)}>{o.number}</button><small>{o.customer} · {o.date}</small></td><td>{idName(users,o.owner)}</td><td>{Object.entries(o.summary.currencies).map(([c,t])=><div key={c}>{cash(t.sale)} {c}<small>待收 {cash(t.receivable)}</small></div>)}{!o.summary.rows.length&&<small>待录入产品</small>}</td><td className="numeric">{cash(o.summary.payable)}</td><td className="numeric">{o.summary.shipped} / {o.summary.quantity}</td><td><span className={'pill '+(o.status==='locked'?'neutral':'blue')}>{o.status==='locked'?'已归档':o.summary.complete?'可归档':'进行中'}</span></td><td><button className="link" onClick={()=>go('order/'+o.id)}>打开 →</button></td></tr>)}</tbody></table></div>;}
function Orders({orders,go,users}){
  const [q,setQ]=useState(''),[status,setStatus]=useState('all');
  const rows=orders.filter(o=>(status==='all'||o.status===status)&&(o.number+' '+o.customer+' '+o.search).toLowerCase().includes(q.toLowerCase()));
  return <><Heading title="订单工作台" sub="按客户或产品查找订单，统一核对每次补单。"><Button onClick={()=>go('new-order')}>＋ 新建订单</Button></Heading><Panel><div className="filter-bar"><input aria-label="搜索订单" placeholder="订单号、客户、产品或型号" value={q} onChange={e=>setQ(e.target.value)}/><Select value={status} onChange={setStatus}><option value="all">全部状态</option><option value="active">进行中</option><option value="locked">已归档</option></Select><span>{rows.length} 个订单</span></div><OrderList orders={rows} go={go} users={users}/></Panel></>;
}
function NewOrder({user,users,go,run,busy,saved}){
  const [data,setData]=useState({number:'ORD-'+today().replaceAll('-','')+'-'+Date.now().toString().slice(-5),customer:'',owner:user.id,date:today(),notes:''}),key=useRef(uuid());
  const set=(k,v)=>setData(d=>({...d,[k]:v}));
  return <><Heading title="新建订单" sub="先建立客户与负责人，再录入产品或后续补单。"><Button secondary onClick={()=>go('orders')}>返回订单列表</Button></Heading><Panel title="客户与订单"><form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();run(async()=>{const result=await api('/orders',{data,key:key.current});await saved(result,'lines/'+result.orderId);});}}><div className="form-grid"><Field label="客户名称 *"><input value={data.customer} onChange={e=>set('customer',e.target.value)} required maxLength={160}/></Field><Field label="负责业务员 *"><Select value={data.owner} onChange={v=>set('owner',v)}>{users.filter(u=>u.active).map(u=><option key={u.id} value={u.id}>{u.username}</option>)}</Select></Field><Field label="订单编号 *"><input value={data.number} onChange={e=>set('number',e.target.value)} required maxLength={60}/></Field><Field label="下单日期 *"><DateInput value={data.date} onChange={v=>set('date',v)}/></Field><Field label="订单备注" wide><textarea value={data.notes} onChange={e=>set('notes',e.target.value)} rows={3}/></Field></div><div className="form-footer"><Button type="submit" disabled={busy}>创建订单，录入产品 →</Button></div></form></Panel></>;
}
function OrderDetail({order,user,users,go,run,busy,saved}){
  const s=summary(order),key=useRef(uuid());
  return <><Heading title={order.number} sub={order.customer+' · 业务员 '+idName(users,order.owner)+' · '+order.date}><Button secondary onClick={()=>run(()=>getDownload('/orders/'+order.id+'/export',order.number+'-对账快照.zip'))}>↓ 下载三表及凭证</Button></Heading>{order.notes&&<div className="notice">{order.notes}</div>}<div className="metrics"><div className="metric"><span>销售 / 已收 / 待收</span>{Object.entries(s.currencies).map(([c,t])=><div key={c}><strong>{cash(t.sale)}<small> {c}</small></strong><small>已收 {cash(t.receipt)} · 待收 {cash(t.receivable)}</small></div>)}</div><div className="metric"><span>已付供应商 · CNY</span><strong>{cash(s.payment)}</strong><small>对外货款 {cash(s.externalCost)}</small></div><div className="metric"><span>待付供应商 · CNY</span><strong>{cash(s.payable)}</strong><small>自供货内部成本 {cash(s.internalCost)}</small></div><div className="metric"><span>累计发货</span><strong>{s.shipped}<small> / {s.quantity} 件</small></strong><small>{order.status==='locked'?'已锁定归档':'按实际数量分批交付'}</small></div></div>
    {order.status==='active'&&<div className="order-actions"><Button secondary onClick={()=>go('lines/'+order.id)}>＋ 产品 / 补单</Button>{user.role==='admin'&&<><Button secondary onClick={()=>go('receipt/'+order.id)}>＋ 客户收款</Button><Button secondary onClick={()=>go('payment/'+order.id)}>＋ 供应商付款</Button></>}<Button onClick={()=>go('shipment/'+order.id)}>新建发货 →</Button></div>}
    <Panel title="产品小项" sub="系统序号与产品型号分列。同型号补单独立核算。"><div className="table-wrap"><table><thead><tr><th scope="col">序号</th><th scope="col">产品 / 型号</th><th scope="col">数量 / 已发 / 未发</th><th scope="col">销售总额</th><th scope="col">已收 / 待收</th><th scope="col">成本 CNY</th><th scope="col">已付 / 待付 CNY</th><th scope="col">供应商 / 条款</th></tr></thead><tbody>{s.rows.map(l=><tr key={l.id}><td className="serial">{l.number}</td><td><ProductName line={l}/><small>{l.date}</small></td><td className="numeric">{l.quantity} / {l.shipped} / <strong>{l.remaining}</strong></td><td className="numeric"><Money amount={l.sale} currency={l.currency}/><small>单价 {price(l.price)}</small></td><td className="numeric"><span className="positive">{cash(l.receipt)}</span><small>待收 {cash(l.receivable)}</small></td><td className="numeric">{cash(l.cost)}<small>单价 {price(l.unitCost)}</small>{l.supplyType==='self'&&<small>内部成本，无对外待付</small>}</td><td className="numeric">{cash(l.payment)}<small>待付 {cash(l.payable)}</small></td><td>{l.supplier}<small>客：{l.customerTerms}</small><small>供：{l.supplierTerms}</small><small>客户运费 {cash(l.freight)} {l.currency} · {l.freightIncluded?'已含':'额外收取'}</small></td></tr>)}</tbody></table>{!s.rows.length&&<Empty>请先录入产品。</Empty>}</div></Panel>
    <Panel title="收付款流水" sub="用途可选填。款项按产品分摊后，才会更新产品结算进度。"><TransactionTable order={order} user={user} go={go}/></Panel>
    <Panel title="发货批次" sub="运费账单可后补，香港换单后可以更新物流单号。">{!order.shipments.length?<Empty>先录入款项，再按实际数量发货。</Empty>:<div className="table-wrap"><table><thead><tr><th scope="col">批次 / 日期</th><th scope="col">产品 / 数量</th><th scope="col">本批待收</th><th scope="col">本批待付 CNY</th><th scope="col">物流</th><th scope="col">实际运费</th><th scope="col"></th></tr></thead><tbody>{order.shipments.map(ship=><tr key={ship.id}><td><strong>批次 #{ship.number}</strong><small>{ship.date}</small></td><td>{ship.items.map(i=><div key={i.lineId}><ProductName line={order.lines.find(l=>l.id===i.lineId)}/><small>{i.quantity} 件</small></div>)}</td><td>{ship.items.map(i=>{const l=order.lines.find(l=>l.id===i.lineId),item=items(order,l.id).find(a=>a.shipmentId===ship.id);return <div key={i.lineId}><Money amount={fixed(due(order,item,'receipt'))} currency={l.currency}/><small>已覆盖 {cash(fixed(covered(order,item,'receipt')))}</small></div>;})}</td><td>{ship.items.map(i=>{const item=items(order,i.lineId).find(a=>a.shipmentId===ship.id);return <div key={i.lineId}>{cash(fixed(due(order,item,'payment')))}<small>已覆盖 {cash(fixed(covered(order,item,'payment')))}</small></div>;})}</td><td>{ship.carrier}<small>国内 {ship.domesticTracking||'—'}</small><small>国际 {ship.internationalTracking||'—'}</small></td><td>{currentFreight(ship).amount===null?<span className="pill amber">待补录</span>:<Money {...{amount:currentFreight(ship).amount,currency:currentFreight(ship).currency}}/>}<small>同批次仅计一次</small></td><td><button className="link" onClick={()=>go('shipment-edit/'+order.id+'/'+ship.id)}>补录运费 / 修改物流 →</button></td></tr>)}</tbody></table></div>}</Panel>
    <Panel title="订单归档" sub="产品款与发货全部完成、无未分摊流水，并人工核对货代运费后才能锁定。"><div className="form-pad">{s.complete&&order.status==='active'&&user.role==='admin'&&<Button disabled={busy} onClick={()=>{if(window.confirm('确认已核对货代运费并锁定订单？锁定后不能再新增或修改业务记录。'))run(async()=>saved(await api('/orders/'+order.id+'/lock',{data:{freightConfirmed:true},key:key.current})));}}>锁定并归档</Button>}{!s.complete&&<p>当前还有未结清产品款、未发数量或未分摊流水。</p>}{order.archives.map(a=><Button secondary key={a.id} onClick={()=>run(()=>getDownload('/orders/'+order.id+'/archive/'+a.id,order.number+'-固化归档.zip'))}>↓ 下载固化归档</Button>)}</div></Panel>
    <AuditList order={order}/></>;
}
function auditText(order,entry){
  const d=entry.detail;if(typeof d==='string')return d;
  if(d?.changes){const labels={internationalTracking:'国际单号',domesticTracking:'国内单号',carrier:'货代',address:'地址',domesticDate:'国内日期',notes:'备注',carrierType:'运输方'};return '批次 #'+d.number+' · '+Object.entries(d.changes).map(([k,v])=>(labels[k]||k)+'：'+(v.before||'空')+' → '+(v.after||'空')).join('；')+'；原因：'+d.reason;}
  if(d?.correction)return '原始公司：'+d.originalParty+'；'+(d.correction.action==='party'?'更正为：'+d.correction.party:'等额反向记录：'+d.correction.delta)+'；原因：'+d.correction.reason;
  if(d?.entries){const txn=order.transactions.find(t=>t.id===d.transactionId);return d.entries.map(e=>(order.lines.find(l=>l.id===e.lineId)?.product||'产品')+'：'+cash(e.amount)+' '+(txn?.currency||'')).join('；');}
  if(d?.items)return '批次 #'+d.number+'；'+d.items.map(i=>(order.lines.find(l=>l.id===i.lineId)?.product||'产品')+' × '+i.quantity+' 件').join('；');
  if(d?.after)return '批次 #'+d.number+'；原运费 '+(d.before?.amount===null?'待补录':cash(d.before?.amount)+' '+d.before?.currency)+' → '+cash(d.after.amount)+' '+d.after.currency+'；'+d.after.reason;
  if(d?.amount)return d.party+' · '+cash(d.amount)+' '+d.currency;
  return '';
}
function AuditList({order}){return <Panel title="操作记录" sub="包含名称更正、误录冲销、单号变更及运费账单历史。"><div className="audit-list">{order.audit.slice(-30).reverse().map(a=><div key={a.id}><strong>{a.action}</strong><span>{a.actor}</span><time>{new Date(a.time).toLocaleString('zh-CN',{hour12:false})}</time><p>{auditText(order,a)}</p></div>)}</div></Panel>;}
function TransactionTable({order,user,go}){
  return !order.transactions.length?<Empty>尚未录入收付款流水。</Empty>:<div className="table-wrap"><table><thead><tr><th scope="col">日期 / 流水号</th><th scope="col">类型</th><th scope="col">公司 / 平台</th><th scope="col">原币金额</th><th scope="col">用途</th><th scope="col">未分配</th><th scope="col">操作</th></tr></thead><tbody>{order.transactions.slice().reverse().map(t=><tr key={t.id}><td>{t.date}<small>{t.reference}</small></td><td><span className={'pill '+(t.kind==='receipt'?'green':'blue')}>{t.kind==='receipt'?'客户收款':'供应商付款'}</span>{voided(t)&&<small className="attention">已冲销误录</small>}</td><td>{effectiveParty(t)}<small>{t.platform}</small></td><td className="numeric"><Money amount={t.amount} currency={t.currency}/>{voided(t)&&<small>原金额，已全额冲销</small>}</td><td>{t.purpose||'—'}</td><td className="numeric">{cash(fixed(available(order,t)))}<small>{t.currency}</small></td><td>{user.role==='admin'&&order.status==='active'&&!voided(t)&&<><button className="link" onClick={()=>go('allocation/'+order.id+'/'+t.id)}>分摊 →</button>{!order.allocations.some(a=>a.transactionId===t.id)&&<small><button className="link" onClick={()=>go('correction/'+order.id+'/'+t.id)}>更正 / 冲销</button></small>}</>}{t.attachment&&<small><a className="link" href={'/api/orders/'+order.id+'/voucher/'+t.id}>下载凭证</a></small>}</td></tr>)}</tbody></table></div>;
}

function LineEntry({order,hints,go,run,busy,saved}){
  const blank=()=>({product:'',model:'',quantity:'',price:'',currency:'USD',supplyType:'external',supplier:'',cost:'',freight:'0'});
  const [rows,setRows]=useState([blank(),blank(),blank()]),[defaults,setDefaults]=useState({date:today(),customerTerms:'发货前结清',supplierTerms:'发货前结清',freightIncluded:true});
  const [rates,setRates]=useState(Object.fromEntries(currencies.filter(c=>c!=='CNY').map(c=>[c,rateFor(order,c,'CNY')||(c==='USD'?'7':'')]))),[file,setFile]=useState(null),[importNote,setImportNote]=useState(''),key=useRef(uuid());
  const active=row=>['product','model','quantity','price','cost'].some(k=>row[k]!=='');
  const update=(index,field,value)=>setRows(old=>old.map((r,i)=>i===index?{...r,[field]:value,...(field==='supplyType'?{supplier:value==='self'?'自供货':r.supplier==='自供货'?'':r.supplier}:{})}:r));
  const used=[...new Set(rows.filter(active).map(r=>r.currency))].filter(c=>c!=='CNY');
  let preview='填写数量、价格和成本后显示金额预览';
  try{
    const totals={};let cost=0n,count=0;
    for(const row of rows.filter(active)){
      const quantity=decimal(row.quantity,0),p=decimal(row.price,4,{max:16}),c=decimal(row.cost,4,{max:16});
      const amount=rounded(quantity*p,100n)+(defaults.freightIncluded?0n:money(row.freight||'0'));
      totals[row.currency]=(totals[row.currency]||0n)+amount;cost+=rounded(quantity*c,100n);count++;
    }
    if(count)preview=count+' 行 · '+Object.entries(totals).map(([c,n])=>cash(fixed(n))+' '+c).join(' / ')+' · 成本 '+cash(fixed(cost))+' CNY';
  }catch{}
  const submit=e=>{e.preventDefault();run(async()=>{const result=await api('/orders/'+order.id+'/lines',{key:key.current,data:{...defaults,rates,rows:rows.filter(active)}});await saved(result,'order/'+order.id);});};
  return <><Heading title="表格录入产品 / 补单" sub={order.number+' · 一行一个产品，系统统一编号。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading><form data-draft onSubmit={submit}>
    <Panel title="固定 Excel 模板导入" sub="导入只回填草稿，核对后点击保存。最多100行，保留已经填写的草稿。" actions={<><Button secondary onClick={()=>download(productTemplate(),'产品录入模板.xlsx','application/vnd.openxmlformats-officedocument.spreadsheetml.sheet')}>↓ 下载 Excel 模板</Button><input type="file" accept=".xlsx" aria-label="产品模板文件" onChange={e=>setFile(e.target.files[0])}/><Button secondary disabled={!file||busy} onClick={()=>run(async()=>{const incoming=await importProducts(file),existing=rows.filter(active);if(existing.length+incoming.length>100)throw Error('当前草稿与导入合计超过100行。');setRows([...existing,...incoming]);setImportNote('已导入 '+incoming.length+' 行草稿，尚未保存到订单。');})}>导入并预览</Button></>}>{importNote&&<div className="notice success">{importNote}</div>}</Panel>
    <Panel title="统一设置" sub="日期、条款和每种币种的报价汇率只填一次。"><div className="form-pad"><div className="form-grid three"><Field label="下单 / 补单日期 *"><DateInput value={defaults.date} onChange={v=>setDefaults(d=>({...d,date:v}))}/></Field><Field label="客户付款约定 *"><input value={defaults.customerTerms} onChange={e=>setDefaults(d=>({...d,customerTerms:e.target.value}))} required/></Field><Field label="供应商付款约定 *"><input value={defaults.supplierTerms} onChange={e=>setDefaults(d=>({...d,supplierTerms:e.target.value}))} required/></Field></div><label className="check-line"><input type="checkbox" checked={defaults.freightIncluded} onChange={e=>setDefaults(d=>({...d,freightIncluded:e.target.checked}))}/>销售单价已含运费</label><div className="rate-strip"><strong>报价汇率</strong><span>CNY 自动为1</span>{used.map(c=><Field key={c} label={'1 '+c+' = CNY'}><NumberInput value={rates[c]} onChange={v=>setRates(r=>({...r,[c]:v}))} step="0.00000001" min="0.00000001"/></Field>)}</div></div></Panel>
    <Panel title="产品与数量" sub="同型号补单保持独立。自供货不产生对外待付。" actions={<Button secondary onClick={()=>rows.length<100&&setRows(r=>[...r,blank()])}>＋ 添加一行</Button>}><div className="table-wrap entry-scroll"><table className="entry-table"><thead><tr><th scope="col">系统序号</th><th scope="col">产品名称 *</th><th scope="col">型号 *</th><th scope="col">数量 *</th><th scope="col">销售单价 *</th><th scope="col">币种 *</th><th scope="col">供货方式 *</th><th scope="col">供应商</th><th scope="col">单位成本 CNY *</th><th scope="col">客户运费</th><th scope="col"></th></tr></thead><tbody>{rows.map((row,index)=><tr key={index}><td className="serial">自动</td><td><Combo value={row.product} onChange={v=>update(index,'product',v)} options={hints.product} required={active(row)} placeholder="产品名称"/></td><td><Combo value={row.model} onChange={v=>update(index,'model',v)} options={hints.model} required={active(row)} placeholder="型号"/></td><td><NumberInput value={row.quantity} onChange={v=>update(index,'quantity',v)} step="1" min="1" required={active(row)}/></td><td><NumberInput value={row.price} onChange={v=>update(index,'price',v)} step="0.0001" min="0.0001" required={active(row)}/></td><td><Currency value={row.currency} onChange={v=>update(index,'currency',v)}/></td><td><Select value={row.supplyType} onChange={v=>update(index,'supplyType',v)}><option value="external">外部供应商</option><option value="self">自供货</option></Select></td><td><Combo value={row.supplier} onChange={v=>update(index,'supplier',v)} options={hints.supplier} readOnly={row.supplyType==='self'} required={active(row)&&row.supplyType!=='self'}/></td><td><NumberInput value={row.cost} onChange={v=>update(index,'cost',v)} step="0.0001" required={active(row)}/></td><td><NumberInput value={row.freight} onChange={v=>update(index,'freight',v)} required={false}/></td><td><button type="button" className="remove" onClick={()=>setRows(r=>r.filter((_,i)=>i!==index))}>移除</button></td></tr>)}</tbody></table></div><div className="entry-summary">{preview}</div></Panel><div className="save-bar"><span>整批校验通过后一起保存。</span><Button type="submit" disabled={busy||!rows.some(active)}>{busy?'正在保存…':'保存全部产品 →'}</Button></div></form></>;
}
function TransactionEntry({kind,order,hints,go,run,busy,saved}){
  const source=kind==='receipt'?'USD':'CNY',target=kind==='receipt'?'USD':'CNY';
  const [data,setData]=useState({kind,date:today(),amount:'',currency:source,party:kind==='receipt'?order.customer:'',platform:'',fx:rateFor(order,source,target)||'1',fxSource:'人工确认',purpose:'',reference:''}),[file,setFile]=useState(null),key=useRef(uuid());
  const set=(k,v)=>setData(d=>({...d,[k]:v,...(k==='currency'?{fx:rateFor(order,v,target)}:{})}));
  let equivalent='填写金额与汇率后显示当日等值';
  try{equivalent='当日等值 '+cash(fixed(rounded(money(data.amount)*decimal(data.fx,8,{max:16}),100000000n)))+' '+target;}catch{}
  return <><Heading title={kind==='receipt'?'录入客户收款':'录入供应商付款'} sub={order.number+' · 保存后按产品分摊，尚未发货也可以录入。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading><Panel title="收付款信息"><form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();run(async()=>{let options={data,key:key.current};if(file){const form=new FormData();form.append('payload',JSON.stringify(data));form.append('voucher',file);options={form,key:key.current};}const result=await api('/orders/'+order.id+'/transaction',options);await saved(result,'allocation/'+order.id+'/'+result.transactionId);});}}><div className="form-grid"><Field label={kind==='receipt'?'收到款的日期 *':'付款日期 *'}><DateInput value={data.date} onChange={v=>set('date',v)}/></Field><Field label="原币金额 *"><NumberInput value={data.amount} onChange={v=>set('amount',v)} min="0.01"/></Field><Field label="原币币种 *"><Currency value={data.currency} onChange={v=>set('currency',v)}/></Field><Field label="平台流水号 *" help="同订单、同类型中保持唯一，冲销后原编号也保留。"><input value={data.reference} onChange={e=>set('reference',e.target.value)} required maxLength={120}/></Field><Field label={kind==='receipt'?'付款公司 *':'供应商名称 *'} help={kind==='payment'?'优先选已有名称；分摊时需与产品供应商一致，误填可在未分摊时更正。':'保存一次后，后续可从下拉列表选择。'}><Combo value={data.party} onChange={v=>set('party',v)} options={kind==='payment'?hints.supplier:hints.party} required/></Field><Field label={kind==='receipt'?'收款平台 *':'付款平台 *'}><Combo value={data.platform} onChange={v=>set('platform',v)} options={hints.platform} required/></Field><Field label="款项用途（选填）" wide><textarea value={data.purpose} onChange={e=>set('purpose',e.target.value)} rows={2} maxLength={240}/></Field><Field label={'当日汇率：1 '+data.currency+' = '+target} help="已填订单汇率自动带出；修改仅影响新记录。"><NumberInput value={data.fx} onChange={v=>set('fx',v)} step="0.00000001" min="0.00000001" readOnly={data.currency===target}/></Field><Field label="汇率来源"><input value={data.fxSource} onChange={e=>set('fxSource',e.target.value)} required maxLength={160}/></Field><Field label="付款水单 / 收款凭证（选填）" help="PDF / PNG / JPG，最大10MB。"><input type="file" accept=".pdf,.png,.jpg,.jpeg" onChange={e=>setFile(e.target.files[0]||null)}/></Field></div><div className="entry-summary">{equivalent}</div><div className="form-footer"><Button type="submit" disabled={busy}>保存流水，去分摊 →</Button></div></form></Panel></>;
}
function AllocationEntry({order,transactionId,user,go,run,busy,saved}){
  const txn=order.transactions.find(t=>t.id===transactionId),key=useRef(uuid());
  const rows=txn?allocationRows(order,txn):[],[selected,setSelected]=useState([]),[amounts,setAmounts]=useState({}),[reason,setReason]=useState('按订单约定分摊'),[detail,setDetail]=useState(false),[batches,setBatches]=useState({});
  const targets=[...new Set(rows.map(l=>txn.kind==='receipt'?l.currency:'CNY'))],[rates,setRates]=useState(Object.fromEntries(targets.map(c=>[c,rateFor(order,txn.currency,c)])));
  if(!txn)return <Empty>流水不存在。</Empty>;
  const used=Object.entries(amounts).filter(([id])=>selected.includes(id)).reduce((n,[,value])=>{try{return n+money(value);}catch{return n;}},0n);
  const existing=order.allocations.filter(a=>a.transactionId===txn.id),allowed=user.role==='admin'&&order.status==='active'&&!voided(txn);
  return <><Heading title="批量款项分摊" sub={order.number+' · 先款后货。每个产品填写一次金额，发货后自动关联批次。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading><div className="transaction-banner"><div><small>{effectiveParty(txn)} · {txn.platform} · {txn.date}</small><strong>{cash(txn.amount)} {txn.currency}</strong></div><div><small>尚可分摊</small><strong>{cash(fixed(available(order,txn)))} {txn.currency}</strong></div><div><small>用途 / 流水号</small><p>{txn.purpose||'未填写用途'} / {txn.reference}</p></div></div>
    {voided(txn)?<Panel title="这笔误录流水已冲销"><Empty>原流水与反向记录保留，不再计入可分摊余额。</Empty></Panel>:available(order,txn)===0n?<Panel title="这笔流水已全部分摊"><Empty>可在下方核对，或返回订单继续发货。</Empty></Panel>:allowed&&<form data-draft onSubmit={e=>{e.preventDefault();run(async()=>{if(!selected.length)throw Error('请勾选要分摊的产品。');const entries=selected.map(id=>({lineId:id,amount:amounts[id]||'',...(detail&&batches[id]?{shipmentId:batches[id]}:{})}));await saved(await api('/orders/'+order.id+'/allocation',{data:{transactionId:txn.id,entries,rates,reason},key:key.current}),'order/'+order.id);});}}>
    <Panel title="选择产品并填写金额" sub="无发货时登记为预付款；有发货时按日期结清欠款，余款供后续发货使用。" actions={<><Button secondary onClick={()=>setSelected(selected.length===rows.length?[]:rows.map(l=>l.id))}>全选 / 取消</Button><Button secondary onClick={()=>run(async()=>{const filled=fillAllocations(order,txn,selected,rates);setAmounts(filled);setSelected(Object.keys(filled));})}>填满所选余额</Button><Button secondary onClick={()=>setAmounts({})}>清空金额</Button></>}><div className="rate-strip"><strong>结算汇率</strong>{targets.map(c=><Field key={c} label={'1 '+txn.currency+' = '+c}><NumberInput value={rates[c]} onChange={v=>setRates(r=>({...r,[c]:v}))} step="0.00000001" min="0.00000001" readOnly={txn.currency===c} required={rows.some(l=>selected.includes(l.id)&&(txn.kind==='receipt'?l.currency:'CNY')===c)}/></Field>)}</div><div className="table-wrap"><table className="allocation-table"><thead><tr><th scope="col"><input aria-label="选择全部产品" type="checkbox" checked={!!rows.length&&selected.length===rows.length} onChange={e=>setSelected(e.target.checked?rows.map(l=>l.id):[])}/></th><th scope="col">序号</th><th scope="col">产品 / 型号</th><th scope="col">总数量</th><th scope="col">已发 / 未发</th>{detail&&<th scope="col">指定批次</th>}<th scope="col">待结算金额</th><th scope="col">本次分摊原币 {txn.currency}</th><th scope="col">预计抵扣</th></tr></thead><tbody>{rows.map(l=>{
      const c=txn.kind==='receipt'?l.currency:'CNY',checked=selected.includes(l.id);let estimate='—';try{estimate=cash(fixed(rounded(money(amounts[l.id])*decimal(rates[c],8,{max:16}),100000000n)))+' '+c;}catch{}
      return <tr key={l.id} className={checked?'selected':''}><td><input type="checkbox" aria-label={'选择 '+l.product} checked={checked} onChange={e=>setSelected(a=>e.target.checked?[...a,l.id]:a.filter(id=>id!==l.id))}/></td><td className="serial">{l.number}</td><td><ProductName line={l}/></td><td className="numeric">{l.quantity}</td><td className="numeric">{l.shipped} / {l.remaining}</td>{detail&&<td><Select required={false} value={batches[l.id]||''} onChange={v=>setBatches(b=>({...b,[l.id]:v}))}><option value="">自动按产品分配</option>{items(order,l.id).filter(i=>due(order,i,txn.kind)>0n).map(i=><option key={i.shipmentId} value={i.shipmentId}>批次 #{order.shipments.find(s=>s.id===i.shipmentId).number} · 待结 {cash(fixed(due(order,i,txn.kind)))}</option>)}</Select></td>}<td className="numeric"><Money amount={txn.kind==='receipt'?l.receivable:l.payable} currency={c}/></td><td><NumberInput value={amounts[l.id]||''} onChange={v=>setAmounts(a=>({...a,[l.id]:v}))} min="0.01" required={checked}/></td><td className="numeric">{estimate}</td></tr>;
    })}</tbody></table>{!rows.length&&<Empty>没有匹配的待结算产品。请检查供应商名称或产品余额。</Empty>}</div><div className="form-pad"><button type="button" className="link" onClick={()=>setDetail(v=>!v)}>{detail?'收起批次明细':'需要指定发货批次？展开明细'}</button><Field label="分摊说明 *"><input value={reason} onChange={e=>setReason(e.target.value)} required maxLength={240}/></Field></div></Panel><div className="save-bar"><span>已选 {selected.length} 行 · 分摊 {cash(fixed(used))} / 可用 {cash(fixed(available(order,txn)))} {txn.currency}</span><Button type="submit" disabled={busy||!selected.length}>确认所选分摊 →</Button></div></form>}
    {allowed&&!existing.length&&<div className="notice">名称填错或流水误录？ <button className="link" onClick={()=>go('correction/'+order.id+'/'+txn.id)}>更正公司名称 / 冲销误录 →</button></div>}
    <Panel title="已有分摊">{!existing.length?<Empty>尚无分摊。</Empty>:<div className="table-wrap"><table><thead><tr><th scope="col">序号</th><th scope="col">产品 / 型号</th><th scope="col">原币金额</th><th scope="col">抵扣金额</th><th scope="col">结算去向</th><th scope="col">说明</th></tr></thead><tbody>{existing.map(a=>{const l=order.lines.find(l=>l.id===a.lineId);return <tr key={a.id}><td className="serial">{l.number}</td><td><ProductName line={l}/></td><td><Money amount={a.source} currency={txn.currency}/></td><td><Money amount={a.target} currency={txn.kind==='receipt'?l.currency:'CNY'}/></td><td>{a.shipmentId?'指定批次 #'+order.shipments.find(s=>s.id===a.shipmentId).number:'按产品分摊'}{a.coverage.map(c=><small key={c.shipmentId}>批次 #{order.shipments.find(s=>s.id===c.shipmentId).number}：{cash(c.amount)}</small>)}<small>未占用余款用于后续发货</small></td><td>{a.reason}</td></tr>;})}</tbody></table></div>}</Panel></>;
}

function ShipmentEntry({order,user,go,run,busy,saved}){
  const rows=summary(order).rows,[selected,setSelected]=useState([]),[quantities,setQuantities]=useState({}),[quotes,setQuotes]=useState(null),key=useRef(uuid());
  const [data,setData]=useState({date:today(),address:'',carrierType:'own',carrier:'',domesticDate:'',domesticTracking:'',internationalTracking:'',freight:'',freightCurrency:'CNY',notes:''});
  const set=(k,v)=>setData(d=>({...d,[k]:v})),setQty=(id,value)=>{setQuantities(q=>({...q,[id]:value}));setQuotes(null);};
  const fill=mode=>{setQuantities(old=>Object.fromEntries(rows.map(l=>[l.id,mode==='clear'?'0':mode==='all'||selected.includes(l.id)?String(l.remaining):(old[l.id]||'0')])));setQuotes(null);};
  const units=Object.values(quantities).reduce((n,v)=>n+(Number(v)||0),0);
  return <><Heading title="本批发货与结算" sub={order.number+' · 先填写数量并预览。运费账单未出时留空，单号可后期更新。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading><form data-draft onSubmit={e=>{e.preventDefault();if(!quotes){run(async()=>setQuotes(quoteShipment(order,quantities)));return;}if(!window.confirm('确认本批已实际发货？数量和占款快照将保存。'))return;run(async()=>saved(await api('/orders/'+order.id+'/shipment',{data:{...data,quantities},key:key.current}),'order/'+order.id));}}>
    <Panel title="选择本批产品" sub="一键全发仅填写未发数量，预览后仍需确认实际发货。" actions={<><Button secondary onClick={()=>fill('all')}>一键全发</Button><Button secondary onClick={()=>fill('selected')}>所选全发</Button><Button secondary onClick={()=>fill('clear')}>清空数量</Button></>}><div className="table-wrap"><table><thead><tr><th scope="col"><input type="checkbox" aria-label="选择全部待发产品" checked={!!rows.filter(l=>l.remaining).length&&selected.length===rows.filter(l=>l.remaining).length} onChange={e=>setSelected(e.target.checked?rows.filter(l=>l.remaining).map(l=>l.id):[])}/></th><th scope="col">序号</th><th scope="col">产品 / 型号</th><th scope="col">订单数量</th><th scope="col">已发</th><th scope="col">未发</th><th scope="col">本次发货数量</th></tr></thead><tbody>{rows.map(l=><tr key={l.id}><td><input type="checkbox" aria-label={'选择发货 '+l.product} disabled={!l.remaining} checked={selected.includes(l.id)} onChange={e=>setSelected(a=>e.target.checked?[...a,l.id]:a.filter(id=>id!==l.id))}/></td><td className="serial">{l.number}</td><td><ProductName line={l}/></td><td className="numeric">{l.quantity}</td><td className="numeric">{l.shipped}</td><td className="numeric">{l.remaining}</td><td><NumberInput value={quantities[l.id]||'0'} onChange={v=>setQty(l.id,v)} step="1" min="0" max={l.remaining} readOnly={!l.remaining}/></td></tr>)}</tbody></table></div><div className="entry-summary">本次填写 {units.toLocaleString()} 件。</div></Panel>
    <Panel title="物流与装箱信息"><div className="form-pad"><div className="form-grid"><Field label="发货日期 *"><DateInput value={data.date} onChange={v=>set('date',v)}/></Field><Field label="运输方 *"><Select value={data.carrierType} onChange={v=>set('carrierType',v)}><option value="own">我们的货代</option><option value="customer">客户货代</option></Select></Field><Field label="货代 / 运输公司 *"><input value={data.carrier} onChange={e=>set('carrier',e.target.value)} required maxLength={160}/></Field><Field label="工厂到货代日期（选填）"><DateInput value={data.domesticDate} onChange={v=>set('domesticDate',v)} required={false}/></Field><Field label="最终收货地址 *" wide><textarea value={data.address} onChange={e=>set('address',e.target.value)} required rows={3}/></Field><Field label="国内单号（选填）"><textarea value={data.domesticTracking} onChange={e=>set('domesticTracking',e.target.value)} rows={2} maxLength={500}/></Field><Field label="国际单号（选填）" help="可先留空，香港转运换单后可修改并保留历史。"><textarea value={data.internationalTracking} onChange={e=>set('internationalTracking',e.target.value)} rows={2} maxLength={500}/></Field><Field label="实际货代运费（选填）" help="账单未出请留空；明确免费填0。发货后由管理员补录。"><NumberInput value={data.freight} onChange={v=>set('freight',v)} required={false}/></Field><Field label="运费币种"><Currency value={data.freightCurrency} onChange={v=>set('freightCurrency',v)}/></Field><Field label="装箱 / 标签 / 产品备注" wide><textarea value={data.notes} onChange={e=>set('notes',e.target.value)} rows={3}/></Field></div><div className="form-footer"><small>预览不扣减数量、不占用款项。</small><Button secondary onClick={()=>run(async()=>setQuotes(quoteShipment(order,quantities)))}>计算本批应收应付 ↓</Button></div></div></Panel>
    {quotes&&<Panel title="本批结算预览" sub="确认时会按最新余额重新计算，允许显示欠款发货。"><div className="table-wrap"><table><thead><tr><th scope="col">产品 / 数量</th><th scope="col">本批货值</th><th scope="col">客户已覆盖</th><th scope="col">本批待收</th><th scope="col">对外货款 CNY</th><th scope="col">供应商已覆盖 CNY</th><th scope="col">本批待付 CNY</th></tr></thead><tbody>{quotes.map(q=>{const l=order.lines.find(l=>l.id===q.lineId);return <tr key={q.lineId}><td><ProductName line={l}/><small>{q.quantity} 件</small></td><td><Money amount={q.receipt.total} currency={l.currency}/></td><td className="positive">{cash(q.receipt.covered)}</td><td className="attention">{cash(q.receipt.due)}</td><td>{cash(q.payment.total)}<small>内部成本 {cash(q.internalCost)}</small></td><td className="positive">{cash(q.payment.covered)}</td><td className="attention">{cash(q.payment.due)}</td></tr>;})}</tbody></table></div><div className="form-pad form-footer"><small>确认保存实际发货数量与占款快照。</small><Button type="submit" disabled={busy}>确认实际发货 →</Button></div></Panel>}</form></>;
}
function ShipmentEdit({order,shipmentId,user,go,run,busy,saved}){
  const ship=order.shipments.find(s=>s.id===shipmentId),freightKey=useRef(uuid()),logisticsKey=useRef(uuid());
  const [bill,setBill]=useState({amount:ship?currentFreight(ship).amount??'':'',currency:ship?currentFreight(ship).currency:'CNY',reason:''});
  const [data,setData]=useState(ship?{address:ship.address,carrier:ship.carrier,carrierType:ship.carrierType,domesticDate:ship.domesticDate,domesticTracking:ship.domesticTracking,internationalTracking:ship.internationalTracking,notes:ship.notes,reason:''}:{});
  const set=(k,v)=>setData(d=>({...d,[k]:v}));
  if(!ship)return <Empty>批次不存在。</Empty>;
  const canEdit=order.status==='active';
  return <><Heading title={'后补运费 / 修改物流 · 批次 #'+ship.number} sub={order.number+' · 数量、货值及发货时占款快照保持原确认结果。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading>
    <Panel title="运费账单" sub={currentFreight(ship).amount===null?'待补录：账单出来后在此登记。':'当前运费 '+cash(currentFreight(ship).amount)+' '+currentFreight(ship).currency}>
    {canEdit&&user.role==='admin'&&<form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();run(async()=>{await saved(await api('/orders/'+order.id+'/freight',{data:{shipmentId:ship.id,...bill},key:freightKey.current}));freightKey.current=uuid();setBill(b=>({...b,reason:''}));});}}><div className="form-grid three"><Field label="本批实际运费总额 *"><NumberInput value={bill.amount} onChange={v=>setBill(b=>({...b,amount:v}))}/></Field><Field label="运费币种 *"><Currency value={bill.currency} onChange={v=>setBill(b=>({...b,currency:v}))}/></Field><Field label="补录 / 更正说明 *"><input value={bill.reason} onChange={e=>setBill(b=>({...b,reason:e.target.value}))} required maxLength={240}/></Field></div><div className="form-footer"><small>更正会追加账单历史，填写本批最新总额。</small><Button type="submit" disabled={busy}>保存运费</Button></div></form>}
    {user.role!=='admin'&&<div className="notice">请管理员登记运费账单。</div>}
    <div className="table-wrap"><table><thead><tr><th scope="col">账单记录</th><th scope="col">金额 / 币种</th><th scope="col">说明</th><th scope="col">操作人 / 时间</th></tr></thead><tbody><tr><td>发货时记录</td><td>{ship.freight===null?'待补录':cash(ship.freight)+' '+ship.freightCurrency}</td><td>原始记录</td><td>{ship.createdBy}</td></tr>{ship.freightRecords.map(b=><tr key={b.id}><td>后补 / 更正</td><td>{cash(b.amount)} {b.currency}</td><td>{b.reason}</td><td>{b.createdBy}<small>{new Date(b.created).toLocaleString('zh-CN')}</small></td></tr>)}</tbody></table></div></Panel>
    <Panel title="物流与单号" sub="支持后填国际单号和香港换单。请填写修改说明，原单号会保留在操作记录。">{canEdit?<form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();run(async()=>{await saved(await api('/orders/'+order.id+'/logistics',{data:{shipmentId:ship.id,...data},key:logisticsKey.current}));logisticsKey.current=uuid();set('reason','');});}}><div className="form-grid"><Field label="运输方"><Select value={data.carrierType} onChange={v=>set('carrierType',v)}><option value="own">我们的货代</option><option value="customer">客户货代</option></Select></Field><Field label="货代 / 运输公司 *"><input value={data.carrier} onChange={e=>set('carrier',e.target.value)} required/></Field><Field label="国内单号"><textarea value={data.domesticTracking} onChange={e=>set('domesticTracking',e.target.value)} rows={2} maxLength={500}/></Field><Field label="国际单号"><textarea value={data.internationalTracking} onChange={e=>set('internationalTracking',e.target.value)} rows={2} maxLength={500}/></Field><Field label="工厂到货代日期"><DateInput value={data.domesticDate} onChange={v=>set('domesticDate',v)} required={false}/></Field><Field label="最终收货地址 *"><textarea value={data.address} onChange={e=>set('address',e.target.value)} required rows={2}/></Field><Field label="装箱 / 标签 / 产品备注"><textarea value={data.notes} onChange={e=>set('notes',e.target.value)} rows={2}/></Field><Field label="修改说明 *" help="例如：香港转运换单号。"><input value={data.reason} onChange={e=>set('reason',e.target.value)} required maxLength={240}/></Field></div><div className="form-footer"><Button type="submit" disabled={busy}>保存物流信息</Button></div></form>:<Empty>订单已锁定，历史信息仅供查看。</Empty>}</Panel><AuditList order={order}/></>;
}
function Correction({order,transactionId,user,hints,go,run,busy,saved}){
  const txn=order.transactions.find(t=>t.id===transactionId),key=useRef(uuid()),[action,setAction]=useState('party'),[party,setParty]=useState(txn?effectiveParty(txn):''),[reason,setReason]=useState('');
  if(!txn)return <Empty>流水不存在。</Empty>;
  const allowed=user.role==='admin'&&order.status==='active'&&!voided(txn)&&!order.allocations.some(a=>a.transactionId===txn.id);
  return <><Heading title="更正公司名称 / 冲销误录" sub={order.number+' · 原流水、凭证和操作痕迹都会保留。'}><Button secondary onClick={()=>go('order/'+order.id)}>返回订单</Button></Heading><div className="transaction-banner"><div><small>{txn.kind==='receipt'?'客户收款':'供应商付款'} · {txn.reference}</small><strong>{cash(txn.amount)} {txn.currency}</strong></div><div><small>当前名称</small><strong>{effectiveParty(txn)}</strong></div></div><Panel title="处理未分摊误录" sub="实际退款不能使用误录冲销；已有分摊的记录不能直接改写。">{!allowed?<Empty>此流水已分摊、已冲销或已锁定，不能直接更正。</Empty>:<form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();if(action==='void'&&!window.confirm('确认这是一笔完全未分摊的误录？系统将追加等额反向记录，并保留原流水。'))return;run(async()=>saved(await api('/orders/'+order.id+'/correction',{data:{transactionId:txn.id,action,party,reason},key:key.current}),action==='party'?'allocation/'+order.id+'/'+txn.id:'order/'+order.id));}}><div className="form-grid"><Field label="处理方式 *"><Select value={action} onChange={setAction}><option value="party">更正公司名称</option><option value="void">冲销完全未分摊的误录流水</option></Select></Field>{action==='party'&&<Field label="正确的公司 / 供应商名称 *"><Combo value={party} onChange={setParty} options={hints.party} required/></Field>}<Field label="更正 / 冲销原因 *" wide><textarea value={reason} onChange={e=>setReason(e.target.value)} required maxLength={240} rows={3}/></Field></div><div className="form-footer"><Button type="submit" disabled={busy}>保存更正 →</Button></div></form>}</Panel></>;
}
function Finance({orders,user,go}){
  const [q,setQ]=useState(''),[kind,setKind]=useState('all'),[pending,setPending]=useState(false);
  const rows=orders.flatMap(o=>o.transactions.map(t=>({...t,order:o}))).filter(t=>(kind==='all'||t.kind===kind)&&(!pending||money(t.unallocated)>0n)&&(t.order.number+' '+t.party+' '+effectiveParty(t)+' '+t.platform+' '+t.reference).toLowerCase().includes(q.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date)||b.created.localeCompare(a.created));
  return <><Heading title="财务流水" sub="按流水核对原币金额；按产品分摊后才更新订单结算余额。"/><Panel><div className="filter-bar"><input aria-label="搜索流水" value={q} onChange={e=>setQ(e.target.value)} placeholder="订单号、公司、平台或流水号"/><Select value={kind} onChange={setKind}><option value="all">全部类型</option><option value="receipt">客户收款</option><option value="payment">供应商付款</option></Select><label className="check-line"><input type="checkbox" checked={pending} onChange={e=>setPending(e.target.checked)}/>只看待分摊</label><span>{rows.length} 笔</span></div><div className="table-wrap"><table><thead><tr><th scope="col">日期 / 流水号</th><th scope="col">订单</th><th scope="col">类型</th><th scope="col">公司 / 平台</th><th scope="col">原币金额</th><th scope="col">用途</th><th scope="col">未分配</th><th scope="col"></th></tr></thead><tbody>{rows.map(t=><tr key={t.id}><td>{t.date}<small>{t.reference}</small></td><td><button className="link" onClick={()=>go('order/'+t.order.id)}>{t.order.number}</button></td><td>{t.kind==='receipt'?'客户收款':'供应商付款'}{voided(t)&&<small>已冲销误录</small>}</td><td>{effectiveParty(t)}<small>{t.platform}</small></td><td><Money amount={t.amount} currency={t.currency}/></td><td>{t.purpose||'—'}</td><td><Money amount={t.unallocated} currency={t.currency}/></td><td>{user.role==='admin'&&t.order.status==='active'&&!voided(t)&&<button className="link" onClick={()=>go('allocation/'+t.order.id+'/'+t.id)}>分摊 →</button>}</td></tr>)}</tbody></table>{!rows.length&&<Empty>没有符合条件的流水。</Empty>}</div></Panel></>;
}
function AllShipments({orders,go}){
  const [q,setQ]=useState('');
  const rows=orders.flatMap(o=>(o.shipments||[]).map(s=>({...s,order:o}))).filter(s=>(s.order.number+' '+s.carrier+' '+s.domesticTracking+' '+s.internationalTracking).toLowerCase().includes(q.toLowerCase())).sort((a,b)=>b.date.localeCompare(a.date));
  return <><Heading title="发货与物流" sub="按批次查看交付、单号及运费账单状态。"/><Panel><div className="filter-bar"><input value={q} onChange={e=>setQ(e.target.value)} placeholder="订单号、货代或物流单号" aria-label="搜索发货"/><span>{rows.length} 个批次</span></div><div className="table-wrap"><table><thead><tr><th scope="col">批次 / 订单</th><th scope="col">日期</th><th scope="col">产品 / 数量</th><th scope="col">运输公司</th><th scope="col">国内 / 国际单号</th><th scope="col">运费</th><th scope="col"></th></tr></thead><tbody>{rows.map(s=><tr key={s.id}><td><strong>批次 #{s.number}</strong><button className="link" onClick={()=>go('order/'+s.order.id)}>{s.order.number}</button></td><td>{s.date}</td><td>{s.items.map(i=><div key={i.lineId}><ProductName line={s.order.summary.rows.find(l=>l.id===i.lineId)}/><small>{i.quantity} 件</small></div>)}</td><td>{s.carrier}</td><td>{s.domesticTracking||'—'}<small>{s.internationalTracking||'—'}</small></td><td>{currentFreight(s).amount===null?<span className="pill amber">运费待补录</span>:<Money amount={currentFreight(s).amount} currency={currentFreight(s).currency}/>}</td><td><button className="link" onClick={()=>go('shipment-edit/'+s.order.id+'/'+s.id)}>补录运费 / 修改物流 →</button></td></tr>)}</tbody></table>{!rows.length&&<Empty>还没有发货记录，请从订单进入“新建发货”。</Empty>}</div></Panel></>;
}
function Team({users,run,busy,saved}){
  const [username,setUsername]=useState(''),[password,setPassword]=useState(''),key=useRef(uuid());
  return <><Heading title="账号与权限" sub="管理员处理财务与全部订单；业务员仅能查看和处理分配给自己的订单。"/><Panel title="已有账号"><div className="table-wrap"><table><thead><tr><th scope="col">账号</th><th scope="col">权限</th><th scope="col">状态</th></tr></thead><tbody>{users.map(u=><tr key={u.id}><td>{u.username}</td><td>{u.role==='admin'?'管理员':'业务员'}</td><td>{u.active?'正常':'已停用'}</td></tr>)}</tbody></table></div></Panel><Panel title="新增业务员"><form className="form-pad" data-draft onSubmit={e=>{e.preventDefault();run(async()=>{await api('/users',{data:{username,password},key:key.current});await saved({});setUsername('');setPassword('');key.current=uuid();});}}><div className="form-grid"><Field label="账号 *" help="3至40位字母、数字或下划线。"><input value={username} onChange={e=>setUsername(e.target.value)} required pattern="[a-zA-Z0-9_]{3,40}" autoComplete="off"/></Field><Field label="初始密码 *" help="至少8位，请分别发给对应同事。"><input type="password" value={password} onChange={e=>setPassword(e.target.value)} required minLength={8} autoComplete="new-password"/></Field></div><div className="form-footer"><Button type="submit" disabled={busy}>创建业务员账号</Button></div></form></Panel></>;
}
function Help(){
  return <><Heading title="使用说明" sub="按实际业务顺序录入，所有修改保留操作痕迹。"/><div className="help-grid">{[
    ['先款后货','建订单和产品 → 录入客户收款或供应商付款 → 勾选产品分摊金额 → 按实际数量发货。尚未发货也能先录入和分摊款项。'],
    ['运费后补','发货时账单未出，实际运费留空。账单出来后进入订单 → 发货批次 → 补录运费 / 修改物流。填写本批运费总额、币种和说明。'],
    ['香港换单号','同一入口更新国际物流单号，并填写换单原因。原单号保留在订单操作记录，发货数量和占款快照不会改动。'],
    ['按产品批量分摊','一个产品一行，显示总数量、已发和未发。发货后的款项仍按产品输入，系统自动结清旧批次，余款供后续发货。也可以展开指定批次。'],
    ['名称与序号','序号由系统生成。公司、供应商和收付款平台保存一次后即可下拉选择；产品名称与型号录入4次后提供建议。全称和简称不会自动当作同一公司。'],
    ['误录更正','完全未分摊的流水可以更正公司名称，或追加等额反向冲销记录。已分摊记录不能直接修改。实际退款不使用误录冲销。'],
    ['Excel表格录入','下载固定模板填写，上传后先回填草稿，核对统一日期、汇率和条款再保存全部产品。最多100行，不支持公式、宏和合并单元格。'],
    ['数据与权限','在线试用数据与本机原系统独立。业务员只能访问自己的订单；管理员可导出三表和凭证。全部结清并核对运费后可锁定归档。'],
  ].map(([title,body])=><Panel key={title} title={title}><p className="help-copy">{body}</p></Panel>)}</div></>;
}
